<template><SilkRoadWorkspace title="音乐与音效库"><section class="head"><div><span>AUDIO LIBRARY</span><h1>营销音乐与音效</h1><p>为营销视频检索背景音乐、转场、强调、成交与环境音效。</p></div></section><el-tabs v-model="tab"><el-tab-pane label="背景音乐" name="music"><div class="search"><el-input v-model="keyword" placeholder="搜索适合目标市场和营销情绪的音乐" @keyup.enter="searchMusic"/><el-button type="primary" :loading="loading" @click="searchMusic">搜索音乐</el-button></div><el-table :data="musicItems" empty-text="输入关键词搜索音乐"><el-table-column label="曲目" min-width="220"><template #default="scope">{{ scope.row.title||scope.row.name||'未命名音乐' }}</template></el-table-column><el-table-column label="作者 / 来源" min-width="180"><template #default="scope">{{ scope.row.artist||scope.row.singer||scope.row.source||'-' }}</template></el-table-column><el-table-column label="试听" width="280"><template #default="scope"><audio :src="musicUrl(scope.row)" controls preload="none"/></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="营销音效" name="sfx"><div class="search"><el-input v-model="keyword" placeholder="搜索转场、按钮、成交、环境等音效" @keyup.enter="searchSfx"/><el-button type="primary" :loading="loading" @click="searchSfx">搜索音效</el-button></div><el-table :data="sfxItems" empty-text="输入关键词搜索营销音效"><el-table-column label="音效" prop="name" min-width="220"/><el-table-column label="类别" prop="category" min-width="160"/><el-table-column label="试听" width="280"><template #default="scope"><audio :src="scope.row.url||scope.row.audio_url||scope.row.preview_url" controls preload="none"/></template></el-table-column></el-table></el-tab-pane></el-tabs></SilkRoadWorkspace></template>
<script setup lang="ts">import{ref}from'vue';import{ElMessage}from'element-plus';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{mediaGenerationAPI}from'@/api/media-generation';import type{MusicSearchItem}from'@/api/music';import type{SoundEffectItem}from'@/api/sfx';const tab=ref('music'),keyword=ref(''),loading=ref(false),musicItems=ref<MusicSearchItem[]>([]),sfxItems=ref<SoundEffectItem[]>([]);const musicUrl=(item:MusicSearchItem)=>item.song_url||item.url||mediaGenerationAPI.music.getMusicStreamUrl(item);const searchMusic=async()=>{if(!keyword.value.trim())return;loading.value=true;try{const r=await mediaGenerationAPI.music.searchMusic({keywords:keyword.value,page_size:30});musicItems.value=r.items||r.songs||[]}catch(e:any){ElMessage.error(e?.message||'音乐搜索失败')}finally{loading.value=false}};const searchSfx=async()=>{loading.value=true;try{sfxItems.value=(await mediaGenerationAPI.soundEffects.searchSoundEffects({keywords:keyword.value,limit:30})).items||[]}catch(e:any){ElMessage.error(e?.message||'音效搜索失败')}finally{loading.value=false}}</script>
<style scoped>.head{margin-bottom:22px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}.search{display:flex;gap:10px;margin:12px 0 20px}audio{height:36px;width:240px}</style>
